import 'package:flutter/material.dart';

/// Custom vector icon widget for Prayer Times (Fajr, Dhuhr, Asr, Maghrib, Isha, Jummah)
/// created from the exact Android Vector Drawable specifications.
class PrayerTimeIcon extends StatelessWidget {
  final String prayerName;
  final Color color;
  final double size;

  const PrayerTimeIcon({
    super.key,
    required this.prayerName,
    this.color = Colors.white,
    this.size = 22.0,
  });

  @override
  Widget build(BuildContext context) {
    return Center(
      child: SizedBox(
        width: size,
        height: size,
        child: CustomPaint(
          painter: _PrayerIconPainter(prayerName: prayerName, color: color),
        ),
      ),
    );
  }
}

class _PrayerIconPainter extends CustomPainter {
  final String prayerName;
  final Color color;

  _PrayerIconPainter({required this.prayerName, required this.color});

  static Path _parseSvgPath(String data) {
    final Path path = Path();
    double currentX = 0;
    double currentY = 0;
    double startX = 0;
    double startY = 0;

    final RegExp regExp =
        RegExp(r'([a-zA-Z])|([-+]?(?:\d*\.\d+|\d+)(?:[eE][-+]?\d+)?)');
    final matches = regExp.allMatches(data).toList();

    int i = 0;
    String command = '';

    double nextNum() {
      if (i < matches.length && matches[i].group(2) != null) {
        final val = double.parse(matches[i].group(2)!);
        i++;
        return val;
      }
      return 0.0;
    }

    while (i < matches.length) {
      final match = matches[i];
      if (match.group(1) != null) {
        command = match.group(1)!;
        i++;
      }

      switch (command) {
        case 'M':
          currentX = nextNum();
          currentY = nextNum();
          startX = currentX;
          startY = currentY;
          path.moveTo(currentX, currentY);
          command = 'L';
          break;
        case 'm':
          currentX += nextNum();
          currentY += nextNum();
          startX = currentX;
          startY = currentY;
          path.moveTo(currentX, currentY);
          command = 'l';
          break;
        case 'L':
          currentX = nextNum();
          currentY = nextNum();
          path.lineTo(currentX, currentY);
          break;
        case 'l':
          currentX += nextNum();
          currentY += nextNum();
          path.lineTo(currentX, currentY);
          break;
        case 'H':
          currentX = nextNum();
          path.lineTo(currentX, currentY);
          break;
        case 'h':
          currentX += nextNum();
          path.lineTo(currentX, currentY);
          break;
        case 'V':
          currentY = nextNum();
          path.lineTo(currentX, currentY);
          break;
        case 'v':
          currentY += nextNum();
          path.lineTo(currentX, currentY);
          break;
        case 'C':
          final x1 = nextNum();
          final y1 = nextNum();
          final x2 = nextNum();
          final y2 = nextNum();
          currentX = nextNum();
          currentY = nextNum();
          path.cubicTo(x1, y1, x2, y2, currentX, currentY);
          break;
        case 'c':
          final dx1 = nextNum();
          final dy1 = nextNum();
          final dx2 = nextNum();
          final dy2 = nextNum();
          final dx = nextNum();
          final dy = nextNum();
          path.cubicTo(
            currentX + dx1,
            currentY + dy1,
            currentX + dx2,
            currentY + dy2,
            currentX + dx,
            currentY + dy,
          );
          currentX += dx;
          currentY += dy;
          break;
        case 'Z':
        case 'z':
          path.close();
          currentX = startX;
          currentY = startY;
          break;
        default:
          i++;
          break;
      }
    }

    return path;
  }

