      ..style = PaintingStyle.fill;

    for (String pathData in paths) {
      final Path path = _parseSvgPath(pathData);
      canvas.drawPath(path, paint);
    }
  }

  @override
  bool shouldRepaint(covariant _PrayerIconPainter oldDelegate) {
    return oldDelegate.prayerName != prayerName || oldDelegate.color != color;
  }
}
